-- A régua de labour do orçamentista: o que o mercado do UK cobra por serviço.
--
-- Colhida ao vivo em 17/08/2026 dos guias de preço de referência (Checkatrade
-- cost guides, MyBuilder pricing guides, PriceYourJob, HouseholdQuotes,
-- hamuch, Rated People, TaskRabbit, Airtasker, e dois operadores fixos de
-- Londres como teto de mercado). 148 referências em 12 trades.
--
-- A regra de precificação que esta tabela serve (fixada pelo dono em 17/08):
--   · handyman é o ÚNICO serviço por tempo (hora / meia diária / diária, fixo);
--   · todo o resto é preço POR SERVIÇO, calibrado por estas referências;
--   · material entra sempre via supplier_prices com margem de 30%.
--
-- Cada linha é o que a FONTE disse, não o nosso preço: low/high/typical em £,
-- includes_materials quando a página declarou (null = não disse), e a nota de
-- Londres quando havia. O orçamentista lê o conjunto e tira o preço; linha
-- torta ficou fora na curadoria (ex.: laminado £40-£50/m2 "labour" que brigava
-- com três fontes em £6-£20 — está só no docs/labour-referencia, marcada).

create table if not exists labour_prices (
  id                 uuid primary key default gen_random_uuid(),
  trade              text not null,
  task               text not null,
  unit               text not null,
  low_gbp            numeric,
  high_gbp           numeric,
  typical_gbp        numeric,
  -- null = a fonte não declarou; o orçamentista trata como "provavelmente com material"
  includes_materials boolean,
  day_rate_gbp       numeric,
  london_note        text,
  source_url         text not null,
  fetched_at         timestamptz not null default now(),
  unique (trade, task)
);

create index if not exists labour_prices_trade_idx on labour_prices (trade);

on conflict (trade, task) do nothing;
